// The first-visit maps (docs/UI-BRIEF.md §7, PLAN §20 D330): a handful of ready-made 128² maps,
// generated by the current generator and checked like any release, one picked at random and loaded
// instantly, with no generation. `tools/first-visit-maps.ts` makes them during the site's deploy
// (D343: never committed) into public/first-visit/: an index and each map's project file (the map
// as the editor opens it: its settings, seed, land, water and objects; gzip JSON). What makes a map fit to be one, and the
// making itself, are plain core functions here (D342 (3), (4)): every map passed over says why.

import { decodeProject } from "../doc/document";
import { MapSession } from "../doc/session";
import { readTimber } from "../format/timber";
import { generate, type GenerateResult } from "../gen/generate";
import { mapName } from "../gen/pack";
import { encodeSpecFragment, makeSpec, THEME_NAMES, type ThemeId } from "../spec/mapspec";
import { validateMap } from "../validate/checks";
import { failing } from "../validate/report";

export const FIRST_VISIT_FORMAT = 1;
/** Their folder under the site's base, and in the repository under public/. */
export const FIRST_VISIT_DIR = "first-visit";
export const FIRST_VISIT_SIZE = 128;

export interface FirstVisitMap {
  id: string;
  /** The project file, relative to the index. */
  file: string;
  name: string;
  theme: ThemeId;
  seed: number;
  /** The map's share fragment (its spec). */
  fragment: string;
  /** The project file's size, and the sha256 of the .timber the map exports as generated. */
  bytes: number;
  sha256: string;
}

export interface FirstVisitIndex {
  format: 1;
  /** The generator that made them: a page on another version generates live instead. */
  generatorVersion: string;
  size: number;
  maps: FirstVisitMap[];
}

/** One map at random, or null when there is none for this generator (the page generates live).
 *  The caller supplies `random` (the page passes `Math.random`): the core uses none of its own (D366). */
export function pickFirstVisit(index: FirstVisitIndex | null, generatorVersion: string, random: () => number): FirstVisitMap | null {
  if (!index || index.format !== FIRST_VISIT_FORMAT || index.generatorVersion !== generatorVersion || !index.maps.length) return null;
  return index.maps[Math.min(index.maps.length - 1, Math.floor(random() * index.maps.length))];
}

/** Why a generated map can't be a first-visit map, one plain reason each (none: it can):
 *  - the generator's own report fails (every blocking check, the starting-logs floor among them,
 *    and item 47's must-haves where the generator has them);
 *  - the written .timber, read back, fails the validator's export profile (every check but
 *    information and the advisory ones), as tools/check-maps.ts checks a probe batch's maps;
 *  - the starting-logs floor fails on the file;
 *  - it misses one of the three outcomes, where the generator reports them (M9b), so a first map
 *    shows its theme. */
export function firstVisitProblems(r: GenerateResult): string[] {
  const out: string[] = [];
  if (!r.report.passed) {
    const failed = r.report.checks.filter((c) => failing(c) && c.severity === "error").map((c) => c.id);
    out.push(`its checks fail (${failed.join(", ") || "the report"})`);
  }
  const v = validateMap(readTimber(r.bytes), { profile: "export", designedFor: r.spec.designedFor });
  const blocking = v.report.checks.filter((c) => failing(c) && c.severity !== "info").map((c) => c.id);
  if (blocking.length) out.push(`its file fails ${blocking.join(", ")}`);
  const floor = v.report.checks.find((c) => c.id === "start.wood_floor");
  if (!floor || !floor.ok) out.push("its file misses the starting-logs floor");
  const outcomes = (r as GenerateResult & { outcomes?: { met: boolean } | null }).outcomes;
  if (outcomes && !outcomes.met) out.push("it misses one of the three outcomes");
  return out;
}

/** Whether a project file reopens as the map it was made from (the same size, land and objects),
 *  from its stored map (D367) and with its replay matching it (D455), and how long opening it took,
 *  in ms. */
export function reopensAs(r: GenerateResult, project: Uint8Array): { same: boolean; ms: number } {
  const t0 = performance.now();
  const s = MapSession.open(decodeProject(project));
  const ms = Math.round(performance.now() - t0);
  const b = s.built;
  const h = r.built.heights;
  let same = b.W === r.built.W && b.H === r.built.H && b.heights.length === h.length && b.entities.length === r.built.entities.length;
  for (let i = 0; same && i < h.length; i++) if (b.heights[i] !== h[i]) same = false;
  return { same: same && s.openedFromStored && s.checkReplay(), ms };
}

export interface FirstVisitMade {
  /** Its index entry but the .timber's sha256, which the tool adds (hashing is the platform's). */
  entry: Omit<FirstVisitMap, "sha256">;
  /** The project file the page loads, and the .timber it exports as generated. */
  project: Uint8Array;
  timber: Uint8Array;
  /** Milliseconds to generate it, and to reopen its project file. */
  genMs: number;
  openMs: number;
}

/** A theme's first-visit map: seeds 1, 2, … up to `maxSeeds` at 128², Designed for Normal, the first
 *  that passes; `passedOver` says why each seed before it didn't. */
export function makeFirstVisit(theme: ThemeId, maxSeeds = 24): { made: FirstVisitMade | null; passedOver: { seed: number; why: string[] }[] } {
  const passedOver: { seed: number; why: string[] }[] = [];
  for (let seed = 1; seed <= maxSeeds; seed++) {
    const t0 = performance.now();
    const r = generate(makeSpec({ seed, theme, size: { x: FIRST_VISIT_SIZE, y: FIRST_VISIT_SIZE } }));
    const genMs = Math.round(performance.now() - t0);
    const why = firstVisitProblems(r);
    if (why.length) {
      passedOver.push({ seed, why });
      continue;
    }
    // (the project file as the editor saves it: with the map stored, so it opens without rebuilding)
    const project = MapSession.fromGenerated(r).project();
    const back = reopensAs(r, project);
    if (!back.same) {
      passedOver.push({ seed, why: ["its project file reopens as a different map"] });
      continue;
    }
    const id = `${THEME_NAMES[theme].toLowerCase().replace(/[^a-z0-9]+/g, "-")}-${seed}`;
    const name = (r as GenerateResult & { name?: string }).name ?? mapName(r.spec);
    return {
      made: { entry: { id, file: `${id}.json.gz`, name, theme, seed, fragment: encodeSpecFragment(r.spec), bytes: project.length }, project, timber: r.bytes, genMs, openMs: back.ms },
      passedOver,
    };
  }
  return { made: null, passedOver };
}
